\begin{tikzpicture}[x=1mm,y=1mm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{xTileFill}{HTML}{DCEBE0}
\definecolor{positiveUnitFill}{HTML}{FCE8D5}
\path[use as bounding box] (0,0) rectangle (50,21);
\foreach \yy in {2.5,8.5,14.5} {
  \draw[black,line width=0.8pt,fill=xTileFill] (4,\yy) rectangle ++(18,4.4);
  \node[black,font=\fontsize{10}{12}\selectfont,inner sep=0pt] at (13,{\yy+2.2}) {$x$};
  \foreach \xx in {24,31} {
    \draw[black,line width=0.8pt,fill=positiveUnitFill] (\xx,\yy) rectangle ++(5,4.4);
    \node[black,font=\fontsize{10}{12}\selectfont,inner sep=0pt] at ({\xx+2.5},{\yy+2.2}) {$1$};
  }
}
\end{tikzpicture}
[/tikz]

